import os
import random
import struct
from typing import Tuple

# This generator produces a complete, valid PNG file as bytes at a small size,
# suitable for libpng read paths exercised by the provided stubs. It supports
# RGB and RGBA, 8-bit depth, small dimensions, non-interlaced, and can include
# a variety of ancillary chunks that the stubs query (PLTE/tRNS/pHYs/sBIT/sRGB/iCCP/
# sPLT/tIME/pCAL/sCAL/unknown, and APNG control chunks in a simple single-frame case).
# The file size stays below 4096 bytes.

# PNG utilities
PNG_SIG = b"\x89PNG\r\n\x1a\n"

def _crc32(data: bytes) -> int:
    # PNG uses standard IEEE CRC-32 (ISO 3309) with polynomial 0x04C11DB7
    import zlib
    return zlib.crc32(data) & 0xFFFFFFFF

def _chunk(typ: bytes, data: bytes) -> bytes:
    return struct.pack(">I", len(data)) + typ + data + struct.pack(">I", _crc32(typ + data))

def _ihdr(width: int, height: int, bit_depth: int, color_type: int,
          interlace: int = 0) -> bytes:
    # compression=0, filter=0 per PNG spec
    data = struct.pack(">IIBBBBB", width, height, bit_depth, color_type, 0, 0, interlace)
    return _chunk(b'IHDR', data)

def _plte(palette: bytes) -> bytes:
    return _chunk(b'PLTE', palette)

def _trns(data: bytes) -> bytes:
    return _chunk(b'tRNS', data)

def _srgb(intent: int) -> bytes:
    return _chunk(b'sRGB', bytes([intent & 3]))

def _sbit(r: int, g: int, b: int, a: int = 0) -> bytes:
    # For truecolor: RGB; for RGBA: RGBA; we’ll emit RGBA-sized if alpha present else RGB-sized
    if a:
        return _chunk(b'sBIT', bytes([r & 0xFF, g & 0xFF, b & 0xFF, a & 0xFF]))
    else:
        return _chunk(b'sBIT', bytes([r & 0xFF, g & 0xFF, b & 0xFF]))

def _phys(xppm: int, yppm: int, unit: int) -> bytes:
    return _chunk(b'pHYs', struct.pack(">IIB", xppm, yppm, unit & 1))

def _time_chunk(y: int, m: int, d: int, hh: int, mm: int, ss: int) -> bytes:
    return _chunk(b'tIME', struct.pack(">H5B", y, m, d, hh, mm, ss))

def _text_chunk(key: str, text: str) -> bytes:
    data = key.encode('latin-1', 'ignore') + b"\x00" + text.encode('latin-1', 'ignore')
    return _chunk(b'tEXt', data)

def _unknown(name4: bytes, payload: bytes) -> bytes:
    # name must be 4 bytes A-Z/a-z
    name4 = bytes([(c if 65 <= c <= 90 or 97 <= c <= 122 else 65) for c in name4[:4].ljust(4, b'A')])
    return _chunk(name4, payload)

def _iCCP(name: str, profile: bytes) -> bytes:
    # iCCP stores: name (latin-1, NUL), compression method=0, then zlib-compressed profile
    import zlib
    comp = zlib.compress(profile, level=6)
    data = name.encode('latin-1', 'ignore') + b"\x00" + b"\x00" + comp
    return _chunk(b'iCCP', data)

def _sPLT(name: str, entries: bytes, depth: int = 8) -> bytes:
    # sPLT: name (NUL), sample depth (8 or 16), then entries
    return _chunk(b'sPLT', name.encode('latin-1', 'ignore') + b"\x00" + bytes([depth]) + entries)

def _pCAL(purpose: str, X0: int, X1: int, typ: int, nparams: int, units: str, params: Tuple[str, ...]) -> bytes:
    # pCAL: purpose\0 X0\0 X1\0 type nparams\0 units\0 p0\0 p1\0 ...
    def asc(n: int) -> bytes:
        return (str(n).encode('ascii') if n >= 0 else (b"-" + str(-n).encode('ascii')))
    buf = bytearray()
    buf += purpose.encode('latin-1', 'ignore') + b"\x00"
    buf += asc(X0) + b"\x00"
    buf += asc(X1) + b"\x00"
    buf += bytes([typ & 0xFF])
    buf += bytes([nparams & 0xFF])
    buf += units.encode('latin-1', 'ignore') + b"\x00"
    for i, p in enumerate(params[:nparams]):
        if i:
            # spec: parameters are NUL-separated, final has no extra NUL (libpng tolerates either)
            pass
        buf += p.encode('latin-1', 'ignore') + b"\x00"
    return _chunk(b'pCAL', bytes(buf))

def _sCAL_strings(unit: int, wstr: str, hstr: str) -> bytes:
    # unit: 1=meters, 2=rad, but libpng accepts 1/2. Strings ASCII numbers
    return _chunk(b'sCAL', bytes([unit & 0xFF]) + wstr.encode('ascii') + b"\x00" + hstr.encode('ascii'))

def _idat_from_rows(rows: bytes) -> bytes:
    import zlib
    # rows is concatenation of scanlines with filter byte per row already included
    comp = zlib.compress(rows, level=6)
    return _chunk(b'IDAT', comp)

def _iend() -> bytes:
    return _chunk(b'IEND', b"")

def _build_image(seed: int) -> bytes:
    rnd = random.Random(seed)
    width = rnd.choice([1, 2, 3])
    height = rnd.choice([1, 2, 3])
    color_type = rnd.choice([2, 6])  # RGB or RGBA
    bit_depth = 8
    interlace = 0

    parts = [PNG_SIG, _ihdr(width, height, bit_depth, color_type, interlace)]

    # Optional PLTE/tRNS for palette images not applicable to truecolor; but tRNS is also valid for truecolor via color_16.
    # Keep focus on chunks used in stubs:
    if rnd.random() < 0.6:
        # pHYs
        xppm = rnd.choice([2835, 4724, 5906, 11811])
        yppm = rnd.choice([2835, 4724, 5906, 11811])
        unit = 1
        parts.append(_phys(xppm, yppm, unit))

    if rnd.random() < 0.5:
        # sRGB
        parts.append(_srgb(rnd.randrange(0, 4)))

    if rnd.random() < 0.5:
        # sBIT consistent with color type
        if color_type == 2:
            parts.append(_sbit(5, 6, 7, 0))
        else:
            parts.append(_sbit(5, 6, 7, 8))

    if rnd.random() < 0.5:
        # tIME within valid ranges
        parts.append(_time_chunk(2020 + rnd.randrange(0, 5), rnd.randrange(1, 13), rnd.randrange(1, 29),
                                 rnd.randrange(0, 24), rnd.randrange(0, 60), rnd.randrange(0, 60)))

    if rnd.random() < 0.4:
        # iCCP small profile
        prof = (b"ICC" + bytes(rnd.randrange(0, 256) for _ in range(rnd.randrange(16, 64))))
        parts.append(_iCCP("ICC", prof))

    if rnd.random() < 0.4:
        # sPLT with 8-bit entries: red,green,blue,alpha,freq (each 2 bytes for sPLT_entry); for depth=8 libpng still uses 2-byte fields
        entries = bytearray()
        n = rnd.randrange(1, 4)
        for i in range(n):
            r = rnd.randrange(0, 256)
            g = rnd.randrange(0, 256)
            b = rnd.randrange(0, 256)
            a = 255
            freq = i + 1
            entries += struct.pack(">5H", r, g, b, a, freq)
        parts.append(_sPLT("sp", bytes(entries), depth=8))

    if rnd.random() < 0.5:
        # pCAL simple, X1 > X0
        X0 = rnd.randrange(0, 50)
        X1 = X0 + rnd.randrange(1, 10)
        typ = rnd.randrange(0, 4)
        nparams = 2
        params = (str(rnd.randrange(0, 10)), str(rnd.randrange(1, 10)))
        parts.append(_pCAL("calib", X0, X1, typ, nparams, "unit", params))

    if rnd.random() < 0.5:
        # sCAL string form; unit 1 or 2
        unit = rnd.choice([1, 2])
        wstr = rnd.choice(["1.0", "1.25", "3.5"])  # positive decimals
        hstr = rnd.choice(["2.0", "2.50", "4.0"])
        parts.append(_sCAL_strings(unit, wstr, hstr))

    if rnd.random() < 0.5:
        # Some textual data
        parts.append(_text_chunk("key", "value0"))
        parts.append(_text_chunk("k1", "value1"))

    if rnd.random() < 0.4:
        # Unknown ancillary chunk
        parts.append(_unknown(bytes([ord('u'), ord('N'), ord('k'), ord('a')]), bytes(rnd.randrange(0, 256) for _ in range(rnd.randrange(0, 16)))))

    # Build image data rows with filter byte per row (0 = None)
    bpp = 3 if color_type == 2 else 4
    rowlen = bpp * width
    rows = bytearray()
    for y in range(height):
        rows.append(0)  # filter None
        # simple pattern but bounded
        for x in range(width):
            r = (x * 85 + y * 17) % 256
            g = (x * 51 + y * 33) % 256
            b = (x * 17 + y * 85) % 256
            if bpp == 3:
                rows += bytes([r, g, b])
            else:
                a = 255
                rows += bytes([r, g, b, a])
    parts.append(_idat_from_rows(bytes(rows)))
    parts.append(_iend())

    data = b"".join(parts)
    # Ensure under 4KiB
    if len(data) > 4096:
        # If exceeded (unlikely), fall back to minimal 1x1 RGB
        data = build_minimal_png()
    return data

def build_minimal_png() -> bytes:
    # 1x1 RGB black
    parts = [PNG_SIG, _ihdr(1, 1, 8, 2, 0)]
    rows = b"\x00\x00\x00\x00"  # filter byte 0 + 3 bytes RGB
    parts.append(_idat_from_rows(rows))
    parts.append(_iend())
    return b"".join(parts)


def generate(seed: int) -> bytes:
    random.seed(seed)
    return _build_image(seed)
